from pathlib import Path
import sys

p = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('psico-engine.js')
s = p.read_text(encoding='utf-8')
marker = "\n/* PLACURSO_PHASE3A_VISIBILITY */\n"
if marker in s:
    raise SystemExit('Fase 3A visibility já aplicada.')

script = r'''\n/* PLACURSO_PHASE3A_VISIBILITY */\n(function(){\n  function boot(){\n    if(document.getElementById('annanPhase3AVisible')) return;\n    var section=document.createElement('section');\n    section.id='annanPhase3AVisible';\n    section.setAttribute('aria-label','ANNAN Fase 3A');\n    var css=document.createElement('style');\n    css.textContent='.p3v{max-width:980px;margin:18px auto;padding:16px;border:2px solid #D9C8A7;border-radius:20px;background:#fffdf8;color:#202A24}.p3v h2{margin:4px 0;font-size:22px}.p3v p{margin:5px 0 12px;color:#756D60;font-size:12px;line-height:1.5}.p3v-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.p3v-card{min-height:145px;padding:12px;border:1px solid #E0D5C2;border-radius:16px;background:#fff;text-align:left;cursor:pointer}.p3v-card strong{display:block;margin-top:7px;font-size:13px}.p3v-card small{display:block;margin-top:5px;color:#756D60;line-height:1.35}.p3v-tag{display:inline-block;margin-top:9px;margin-right:4px;padding:4px 6px;border-radius:999px;background:#F1ECE3;font-size:8px;font-weight:900}.p3v-panel{display:none;margin-top:12px;padding:14px;border-radius:15px;background:#F9F5EC;border:1px solid #D9C8A7}.p3v-panel.open{display:block}.p3v-options{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.p3v-btn{min-height:48px;border:1px solid #D7CDBD;border-radius:12px;background:#fff;font-weight:900}.p3v-btn.primary{background:#202A24;color:#fff}.p3v-level{font-size:10px;color:#756D60}.p3v-result{margin-top:10px;padding:10px;border-radius:12px;background:#EEE6D6;font-size:12px;line-height:1.45}@media(max-width:720px){.p3v-grid{grid-template-columns:1fr 1fr}.p3v-options{grid-template-columns:1fr}.p3v{margin:14px 0;padding:13px}}@media(max-width:430px){.p3v-grid{grid-template-columns:1fr}}';\n    document.head.appendChild(css);\n    section.innerHTML='<div class="p3v"><div class="pch-games-eyebrow">ANNAN · FASE 3A</div><h2>Experiências que evoluem</h2><p>Esta é a nova camada de jogos: quatro experiências, etiquetas, níveis e progressão. Começa simples e ganha complexidade.</p><div class="p3v-grid"><button class="p3v-card" data-g="memoria"><span style="font-size:25px">🧠</span><strong>Memória em cadeia</strong><small>Reconstrua uma sequência.</small><span class="p3v-tag">MEMÓRIA</span><span class="p3v-tag">MENTE</span></button><button class="p3v-card" data-g="reflexo"><span style="font-size:25px">⚡</span><strong>Reflexo rápido</strong><small>Encontre o sinal certo.</small><span class="p3v-tag">REFLEXO</span><span class="p3v-tag">FOCO</span></button><button class="p3v-card" data-g="dinheiro"><span style="font-size:25px">💰</span><strong>Decisão financeira</strong><small>Escolha com margem e risco.</small><span class="p3v-tag">DINHEIRO</span><span class="p3v-tag">DECISÃO</span></button><button class="p3v-card" data-g="negocio"><span style="font-size:25px">♟</span><strong>Mini negócio</strong><small>Administre recursos e clientes.</small><span class="p3v-tag">NEGÓCIO</span><span class="p3v-tag">ESTRATÉGIA</span></button></div><div class="p3v-panel" id="p3vPanel"></div></div>';\n    var target=document.querySelector('.pch-games-hub') || document.querySelector('#annanChallengeCard') || document.querySelector('main') || document.body;\n    if(target && target.parentNode && target.classList && target.classList.contains('pch-games-hub')) target.appendChild(section); else if(target && target.parentNode) target.parentNode.insertBefore(section,target.nextSibling); else document.body.appendChild(section);\n    var panel=section.querySelector('#p3vPanel'), level=1, xp=0;\n    var qs={memoria:[['Sequência: 3 · 8 · 2. Qual vem primeiro?','3','8'],['Sequência: 6 · 1 · 9. Qual é o último?','9','1'],['Sequência: 4 · 7 · 5. Qual é o meio?','7','4']],reflexo:[['Qual é o diferente? ● ● ○ ●','○','●'],['Responda ao quadrado: ■ ● ● ●','■','●'],['Responda ao triângulo: ● ▲ ● ●','▲','●']],dinheiro:[['Venda 100, custo 70. Margem sobre preço?','30%','70%'],['Custo 80, venda 120. Lucro?','40','200'],['Preço 200, custo 150. Baixa 10: lucro?','40','50']],negocio:[['Pouca capacidade e 3 clientes. Primeiro passo?','Priorizar pedidos','Aceitar tudo'],['Vendas caíram. Primeiro?','Descobrir a causa','Dar desconto'],['Produto vende muito e dá pouco lucro.','Rever a margem','Produzir mais']]};\n    function play(kind){var q=qs[kind][Math.floor(Math.random()*qs[kind].length)];panel.classList.add('open');panel.innerHTML='<strong>'+section.querySelector('[data-g="'+kind+'"] strong').textContent+'</strong><div class="p3v-level">Nível '+level+' · '+xp+' XP · tempo '+(level===1?'30':'45')+'s</div><div style="margin-top:12px;font-size:17px;font-weight:900">'+q[0]+'</div><div class="p3v-options"><button class="p3v-btn primary" data-a="1">'+q[1]+'</button><button class="p3v-btn" data-a="0">'+q[2]+'</button></div>';panel.querySelectorAll('[data-a]').forEach(function(b){b.addEventListener('click',function(){var ok=b.dataset.a==='1';xp+=ok?level*10:2;if(ok&&level<3)level++;panel.innerHTML='<div class="p3v-result"><strong>'+(ok?'Acerto.':'Tentativa registada.')+'</strong><br>ANNAN: '+xp+' XP · Nível '+level+'. O próximo nível acrescenta experiência.</div><button class="p3v-btn primary" style="width:100%;margin-top:9px" id="p3vAgain">Continuar</button>';panel.querySelector('#p3vAgain').addEventListener('click',function(){play(kind);});});});}\n    section.querySelectorAll('[data-g]').forEach(function(b){b.addEventListener('click',function(){play(b.dataset.g);});});\n  }\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot); else boot();\n})();\n'''
script = script.replace(r'\n', '\n')
s += marker + script
p.write_text(s, encoding='utf-8')
print('OK: fallback visual da Fase 3A adicionada.')
